CREATE FUNCTION tiktok_stock_sync_follows_orders_apply() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.orders_apply_enabled AND NOT NEW.orders_apply_enabled AND NEW.stock_sync_enabled THEN
    NEW.stock_sync_enabled := false;
    NEW.stock_sync_changed_at := now();
    NEW.stock_sync_changed_by_staff_user_id := coalesce(NEW.orders_apply_changed_by_staff_user_id, OLD.stock_sync_changed_by_staff_user_id);
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
